-- 43 Night Market: walks the listener, keeps the camera on it, tosses coins
-- and draws each sound's rings. What is heard - each loop swelling as you
-- pass and sitting to your left or right, and the coin from where it lands -
-- is the engine's positional audio (`spatial` sources, the player's
-- `audio_listener`, `Audio.play_sound_at`). Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/43-night-market.scene"
local HALF = 1300.0
local SPEED = 280
local SOURCES = {
    { name = "Musician", x = -880.0, y = 40.0, r = 1.0, g = 0.26327, b = 0.69207 },
    { name = "Grill", x = -350.0, y = 175.0, r = 1.0, g = 0.26327, b = 0.0331 },
    { name = "Fountain", x = 300.0, y = -20.0, r = 0.21404, g = 0.60383, b = 1.0 },
    { name = "Chimes", x = 900.0, y = -170.0, r = 1.0, g = 0.78741, b = 0.21404 }
}
local post_on = nav.post_all_on(SCENE)
local captions = true
local player, light, cam, glint, status
local px, py = -1100, -40
local t = 0

function init(entity)
    player = Entity.find_by_name("Player")
    light = Entity.find_by_name("PlayerLight")
    cam = Entity.find_by_name("Camera")
    glint = Entity.find_by_name("Glint")
    status = Entity.find_by_name("Status")
    for _, s in ipairs(SOURCES) do
        s.rings = {}
        for k = 1, 3 do s.rings[k] = Entity.find_by_name(s.name .. "Ring" .. k) end
    end
end

local function held(a, b) return Input.is_key_pressed(a) or Input.is_key_pressed(b) end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    local dx, dy = 0, 0
    if held("A", "Left") then dx = dx - 1 end
    if held("D", "Right") then dx = dx + 1 end
    if held("W", "Up") then dy = dy + 1 end
    if held("S", "Down") then dy = dy - 1 end
    px = math.max(-HALF + 40, math.min(HALF - 40, px + dx * SPEED * dt))
    py = math.max(-190, math.min(150, py + dy * SPEED * dt))
    if player then Transform.set_position(player, px, py) end
    if light then Transform.set_position(light, px, py) end
    if cam then Transform.set_position(cam, math.max(-HALF + 640, math.min(HALF - 640, px)), 0) end

    -- Each source's rings drift outward, brighter the nearer you stand.
    local nearest, best = nil, 1e9
    for _, s in ipairs(SOURCES) do
        local d = math.sqrt((s.x - px) ^ 2 + (s.y - py) ^ 2)
        if d < best then best, nearest = d, s.name end
        local near = math.max(0, 1 - d / 900)
        for k, r in ipairs(s.rings) do
            if r then
                local phase = (t * 0.5 + k / 3) % 1
                Transform.set_scale(r, 0.6 + phase * 2.6, 0.6 + phase * 2.6)
                Sprite.set_color(r, s.r, s.g, s.b, (1 - phase) * 0.55 * near)
            end
        end
    end
    if status then UI.set_text(status, "loudest: " .. string.lower(nearest or "")) end

    if Input.is_mouse_left_just_pressed() then
        local mx, my = Input.get_mouse_world_position()
        Audio.play_sound_at("sounds/market_coin.wav", mx, my, 0.9)
        if glint then
            Transform.set_position(glint, mx, my)
            Particles.emit_burst(glint, 18)
        end
    end
end
